/*
 * The table of a "dvars" tab: one table per game, set up by the game's
 * js/<game>/dvars.js with window.DvarTable(config).
 *
 * The data is the game's js/<game>/dvars-data.js, generated by a script in
 * tools/ (what each field means is written at the top of the data file). A
 * field the sources do not state is missing and shows as a dash; nothing is
 * filled in by guessing.
 *
 * The rows are built once. Search, the filters and sorting only hide and
 * reorder them, so typing stays cheap with over a thousand of them. A click
 * on a name copies it as a config line with its default; a click on a
 * protection tag
 * (or the small "i" of a protection without a tag) opens a popover with the
 * reason and the source it comes from.
 *
 * config:
 *   data         the entries
 *   panel        id of the tab's panel
 *   prefix       prefix of the element ids: <prefix>-body, -search, -count,
 *                -empty, -protection, -sort, -hint, -pop, -pop-title,
 *                -pop-text, -pop-ref
 *   sources      { key: name } of the sources, in the order they show
 *   defaultFrom  { dn value: note } for defaults that come from a config
 *   protections  { type: { show, label, title } }: show is "cheat" (orange
 *                tag), "enforced" (outlined tag), "tag" (grey tag) or "info"
 *                (no tag, only the "i"); a type not listed shows nothing
 */
(function ()
{
	"use strict";

	var escapeHtml = window.UI.escapeHtml;
	var copyText = window.UI.copyText;

	var TAG_CLASSES = { cheat: "d2-cheat", enforced: "dv-tag dv-tag-enforced", tag: "dv-tag" };
	var POP_GAP = 6;
	var POP_MARGIN = 16;

	// Numbers already carry a point; "inf" is the engine's FLT_MAX / INT_MAX.
	function showValue(value)
	{
		if (value === undefined || value === null)
		{
			return null;
		}
		if (value === "inf")
		{
			return "∞";
		}
		if (value === "-inf")
		{
			return "−∞";
		}
		return String(value);
	}

	function cell(value, className)
	{
		var shown = showValue(value);
		// a field no source states: a dash here, left out on a phone
		return '<td class="' + className + (shown === null ? " d2-blank" : "") + '">' +
			(shown === null ? '<span class="d2-none">&mdash;</span>'
				: shown === "" ? '<span class="d2-empty">""</span>' : escapeHtml(shown)) + "</td>";
	}

	// seta <name> "<default>"; a dvar without a known default gets "".
	function configLine(entry)
	{
		var value = entry.d === undefined || entry.d === null ? "" : showValue(entry.d);
		if (value === "∞" || value === "−∞")
		{
			value = "";
		}
		return "seta " + entry.n + ' "' + String(value).replace(/"/g, "") + '"';
	}

	function protectionType(entry)
	{
		return entry.p ? entry.p[0] : "none";
	}

	function DvarTable(config)
	{
		var entries = [];
		var rows = [];
		var body = null;
		var searchBox = null;
		var countBox = null;
		var emptyBox = null;
		var protectionBox = null;
		var sourceBoxes = [];
		var sortButton = null;
		var sortHeader = null;
		var hint = null;
		var setHint = function () {};
		var ascending = true;
		var pop = null;
		var popTitle = null;
		var popText = null;
		var popRef = null;
		var popOwner = null;

		function byId(suffix)
		{
			return document.getElementById(config.prefix + "-" + suffix);
		}

		function defaultCell(entry)
		{
			var html = cell(entry.d, "d2-def");
			var extra = "";
			if (entry.dn && config.defaultFrom[entry.dn])
			{
				extra += ' <span class="d2-note" title="' + escapeHtml(config.defaultFrom[entry.dn]) + '">cfg</span>';
			}
			// another source registers it with a different default or range
			if (entry.x)
			{
				Object.keys(entry.x).forEach(function (source)
				{
					var alt = entry.x[source];
					var parts = [];
					if (alt.default !== undefined)
					{
						parts.push(showValue(alt.default));
					}
					if (alt.min !== undefined || alt.max !== undefined)
					{
						parts.push("range " + (showValue(alt.min) || "?") + " – " + (showValue(alt.max) || "?"));
					}
					extra += '<span class="d2-alt">' + escapeHtml(config.sources[source] + ": " + parts.join(", ")) +
						"</span>";
				});
			}
			return extra === "" ? html : html.replace(/<\/td>$/, extra + "</td>");
		}

		function tagHtml(entry, index)
		{
			var spec = config.protections[protectionType(entry)];
			if (!spec)
			{
				return "";
			}
			var attrs = ' type="button" data-tag="' + index + '" aria-expanded="false" aria-controls="' +
				config.prefix + '-pop" title="' + escapeHtml(entry.p[1]) + '"';
			if (spec.show === "info")
			{
				return ' <button class="dv-info dv-tagbtn"' + attrs + ' aria-label="' + escapeHtml(spec.title) +
					': why">i</button>';
			}
			return ' <button class="' + TAG_CLASSES[spec.show] + ' dv-tagbtn"' + attrs + ">" +
				escapeHtml(spec.label) + "</button>";
		}

		function rowHtml(entry, index)
		{
			var name = '<button class="d2-name" type="button" data-index="' + index + '" title="Copy as config line">' +
				escapeHtml(entry.n) + "</button>" + tagHtml(entry, index);

			var desc = entry.ds ? escapeHtml(entry.ds) : '<span class="d2-none">&mdash;</span>';
			if (entry.dsn)
			{
				desc += ' <span class="d2-from">' + escapeHtml(entry.dsn) + "</span>";
			}
			if (entry.v && entry.v.length)
			{
				desc += '<span class="d2-values">values: ' + entry.v.map(escapeHtml).join(" &middot; ") + "</span>";
			}

			var sources = entry.s.map(function (s)
			{
				return '<span class="d2-src d2-src-' + s + '">' + config.sources[s] + "</span>";
			}).join("");

			return '<tr class="d2-row">' +
				'<td class="d2-namecell" data-label="Name">' + name + "</td>" +
				defaultCell(entry).replace("<td ", '<td data-label="Default" ') +
				cell(entry.mn, "d2-num").replace("<td ", '<td data-label="Min" ') +
				cell(entry.mx, "d2-num").replace("<td ", '<td data-label="Max" ') +
				cell(entry.t, "d2-type").replace("<td ", '<td data-label="Type" ') +
				'<td class="d2-desc' + (entry.ds || (entry.v && entry.v.length) ? "" : " d2-blank") +
					'" data-label="Description">' + desc + "</td>" +
				'<td class="d2-sources" data-label="Source">' + sources + "</td>" +
				"</tr>";
		}

		function render()
		{
			var html = [];
			for (var i = 0; i < entries.length; i++)
			{
				html.push(rowHtml(entries[i], i));
			}
			body.innerHTML = html.join("");
			rows = [].slice.call(body.querySelectorAll(".d2-row"));
		}

		/* ---------- protection popover ---------- */

		function closePop(returnFocus)
		{
			if (pop === null || pop.hidden)
			{
				return;
			}
			pop.hidden = true;
			if (popOwner !== null)
			{
				popOwner.setAttribute("aria-expanded", "false");
				if (returnFocus)
				{
					popOwner.focus();
				}
			}
			popOwner = null;
		}

		// Below the tag, kept inside the window; above it when there is no room below.
		function placePop(button)
		{
			var parent = pop.offsetParent || document.body;
			var box = parent.getBoundingClientRect();
			var at = button.getBoundingClientRect();
			var left = Math.min(at.left, document.documentElement.clientWidth - POP_MARGIN - pop.offsetWidth);
			left = Math.max(POP_MARGIN, left);
			var top = at.bottom + POP_GAP;
			if (top + pop.offsetHeight > window.innerHeight - POP_MARGIN &&
				at.top - POP_GAP - pop.offsetHeight > POP_MARGIN)
			{
				top = at.top - POP_GAP - pop.offsetHeight;
			}
			pop.style.left = (left - box.left + parent.scrollLeft) + "px";
			pop.style.top = (top - box.top + parent.scrollTop) + "px";
		}

		function openPop(button)
		{
			var entry = entries[Number(button.getAttribute("data-tag"))];
			closePop(false);
			popTitle.textContent = entry.n + " — " + config.protections[protectionType(entry)].title;
			popText.textContent = entry.p[1];
			var ref = entry.p[2] ? "Source: " + entry.p[2] : "";
			if (entry.f !== undefined)
			{
				ref += (ref ? " · " : "") + "flags 0x" + entry.f.toString(16).toUpperCase();
			}
			popRef.textContent = ref;
			popRef.hidden = ref === "";
			pop.hidden = false;
			popOwner = button;
			button.setAttribute("aria-expanded", "true");
			placePop(button);
		}

		/* ---------- filtering and sorting ---------- */

		function setCount(shown)
		{
			if (countBox !== null)
			{
				countBox.textContent = shown === entries.length
					? entries.length + " dvars"
					: shown + " of " + entries.length + " dvars";
			}
		}

		function protectionMatches(entry, wanted)
		{
			if (wanted === "")
			{
				return true;
			}
			if (wanted === "cheat")
			{
				return entry.c === true;
			}
			return protectionType(entry) === wanted;
		}

		function applyFilter()
		{
			var query = searchBox === null ? "" : searchBox.value.trim().toLowerCase();
			var wanted = protectionBox === null ? "" : protectionBox.value;
			var sources = {};
			sourceBoxes.forEach(function (box)
			{
				sources[box.getAttribute("data-source")] = box.checked;
			});

			closePop(false);
			var shown = 0;
			for (var i = 0; i < entries.length; i++)
			{
				var e = entries[i];
				var match = (query === "" || e.haystack.indexOf(query) !== -1) &&
					protectionMatches(e, wanted) &&
					e.s.some(function (s) { return sources[s]; });
				rows[i].hidden = !match;
				if (match)
				{
					shown++;
				}
			}

			setCount(shown);
			if (emptyBox !== null)
			{
				emptyBox.hidden = shown !== 0;
				if (shown === 0)
				{
					emptyBox.textContent = query === "" ? "No dvar matches these filters."
						: 'No dvar matches "' + query + '" with these filters.';
				}
			}
		}

		function sortRows()
		{
			var order = rows.slice().sort(function (a, b)
			{
				var x = entries[Number(a.querySelector(".d2-name").getAttribute("data-index"))].key;
				var y = entries[Number(b.querySelector(".d2-name").getAttribute("data-index"))].key;
				return (x < y ? -1 : x > y ? 1 : 0) * (ascending ? 1 : -1);
			});
			order.forEach(function (row) { body.appendChild(row); });
			if (sortHeader !== null)
			{
				sortHeader.setAttribute("aria-sort", ascending ? "ascending" : "descending");
			}
			if (sortButton !== null)
			{
				sortButton.querySelector(".d2-arrow").textContent = ascending ? "▲" : "▼";
				sortButton.title = ascending ? "Sorted A to Z; click for Z to A" : "Sorted Z to A; click for A to Z";
			}
		}

		/* ---------- copy ---------- */

		function onListClick(event)
		{
			var tag = event.target.closest ? event.target.closest(".dv-tagbtn") : null;
			if (tag !== null)
			{
				if (popOwner === tag)
				{
					closePop(false);
				}
				else
				{
					openPop(tag);
				}
				return;
			}
			var button = event.target.closest ? event.target.closest(".d2-name") : null;
			if (button === null)
			{
				return;
			}
			var line = configLine(entries[Number(button.getAttribute("data-index"))]);
			copyText(line).then(function ()
			{
				setHint("Copied: " + line);
			}, function ()
			{
				setHint("Could not copy — select the text and copy manually.", true);
			});
		}

		/* ---------- wiring ---------- */

		function init()
		{
			body = byId("body");
			if (body === null || !config.data)
			{
				return;
			}
			searchBox = byId("search");
			countBox = byId("count");
			emptyBox = byId("empty");
			protectionBox = byId("protection");
			sourceBoxes = [].slice.call(document.querySelectorAll("#" + config.panel + " [data-source]"));
			sortButton = byId("sort");
			sortHeader = sortButton !== null ? sortButton.closest("th") : null;
			hint = byId("hint");
			setHint = window.UI.hint(hint);
			pop = byId("pop");
			popTitle = byId("pop-title");
			popText = byId("pop-text");
			popRef = byId("pop-ref");

			entries = config.data.map(function (e)
			{
				e.key = e.n.toLowerCase();
				e.haystack = (e.n + " " + (e.ds || "")).toLowerCase();
				return e;
			});

			render();
			sortRows();
			setCount(entries.length);

			if (searchBox !== null)
			{
				searchBox.addEventListener("input", applyFilter);
				searchBox.addEventListener("search", applyFilter);
			}
			if (protectionBox !== null)
			{
				protectionBox.addEventListener("change", applyFilter);
			}
			sourceBoxes.forEach(function (box) { box.addEventListener("change", applyFilter); });
			if (sortButton !== null)
			{
				sortButton.addEventListener("click", function ()
				{
					closePop(false);
					ascending = !ascending;
					sortRows();
				});
			}
			body.addEventListener("click", onListClick);

			// The popover closes on Escape, a click elsewhere, a resize and when
			// another tab opens.
			document.addEventListener("keydown", function (event)
			{
				if (event.key === "Escape")
				{
					closePop(true);
				}
			});
			document.addEventListener("click", function (event)
			{
				if (popOwner !== null && !pop.contains(event.target) && !popOwner.contains(event.target))
				{
					closePop(false);
				}
			});
			window.addEventListener("resize", function () { closePop(false); });
			document.addEventListener("tabchange", function () { closePop(false); });
		}

		if (document.readyState === "loading")
		{
			document.addEventListener("DOMContentLoaded", init);
		}
		else
		{
			init();
		}
	}

	window.DvarTable = DvarTable;
})();
